<?php $catalogItems=[['id'=>0,'name'=>'','description'=>'','price'=>null,'stock'=>null,'active'=>1,'category'=>'Solar panels'],...$items]; ?>
<p>Publish only verified company offerings. Blank prices mean “to be confirmed”; blank stock means availability is not specified.</p>
<?php foreach($catalogItems as $item): ?><details class="panel" <?= !$item['id']?'open':'' ?>><summary><?= $item['id']?'Edit #'.(int)$item['id'].' · '.esc($item['name']):'Add '.($kind==='products'?'product':'service') ?></summary><form action="<?= site_url('manage/'.$kind.'/'.$item['id']) ?>" method="post"><?= csrf_field() ?><label>Name<input name="name" value="<?= esc($item['name'],'attr') ?>" maxlength="100" required></label><label>Description<textarea name="description" maxlength="5000" rows="4" required><?= esc($item['description']) ?></textarea></label>
<?php if($kind==='products'): ?><div class="form-grid"><label>Category<select name="category"><?php foreach(['Solar panels','Inverters','Batteries','Mounting equipment','Wires'] as $category): ?><option <?= ($item['category']??'')===$category?'selected':'' ?>><?= esc($category) ?></option><?php endforeach ?></select></label><label>Stock (optional)<input name="stock" type="number" min="0" step="1" value="<?= esc($item['stock']??'','attr') ?>"></label></div><?php endif ?><div class="form-grid"><label>Price (PHP, optional)<input name="price" type="number" min="0" step="0.01" value="<?= esc($item['price']??'','attr') ?>"></label><label>Availability<select name="active"><option value="1" <?= $item['active']?'selected':'' ?>>Published / available</option><option value="0" <?= !$item['active']?'selected':'' ?>>Unavailable / hidden</option></select></label></div><button type="submit">Save <?= $kind==='products'?'product':'service' ?></button></form></details><?php endforeach ?>
